  _killChild(session) {
    try {
      process.kill(-session.child.pid, 'SIGKILL');
    } catch {
      try { session.child.kill('SIGKILL'); } catch { /* already gone */ }
    }
  }

  // -------------------------------------------------------------------------
  // prompt() — XA7: turn (native multi-turn) / nudge (emulated) / steer (native)
  // -------------------------------------------------------------------------

  async prompt(worker, content, mode = 'turn') {
