      ...(this._cfg.args ?? []),
      ...buildClaudeSessionArgs({
        approvals: this._cfg.approvals,
        sessionId: opts.session?.id ?? this._cfg.sessionId,
        forkSession: opts.session?.mode === 'fork',
        model: opts.model ?? this._cfg.model,
