    this._taskOrder.push(taskId);

    const handle = {
      id: workerId,
      vendor: vendor === 'auto' ? null : vendor,
      modelRequested: opts.model ?? null,
      modelResolved: null,
      modelObserved: null,
      effortRequested,
      effortResolved: null,
      effortObserved: null,
      modelPolicy,
      sessionRequest,
      sessionContext: task.sessionContext,
      lineage: task.lineage,
